-- ============================================================================
--  CDE System — SEED BỘ LUẬT KIỂM LOI (PostgreSQL / Npgsql, EF Core schema)
-- ----------------------------------------------------------------------------
--  Mục đích : nạp bộ luật đối chiếu thông tin phi hình học theo
--             QĐ 347/QĐ-BXD — PHỤ LỤC 02 vào 3 bảng "LoiRequirements",
--             "LoiComponents", "LoiFieldAliases" (dữ liệu tham chiếu, không phải dữ liệu test).
--
--  SINH TỰ ĐỘNG — KHÔNG SỬA TAY FILE NÀY.
--    Nguồn : FE/Capstone_Project_FE/docs/BXD_347-QD-BXD_02042021_TailieuHDChiTiet (LOD).xlsx
--    Script: FE/Capstone_Project_FE/docs/loi/tools/gen_seed_sql.py
--    Sửa bảng chuẩn → chạy lại script → thay file này.
--
--  CÁCH CHẠY :
--    psql -h localhost -U <user> -d <database> -f seed_loi_rules.sql
--    (hoặc dán toàn bộ vào pgAdmin / DBeaver Query Tool rồi Execute)
--
--  ĐẶC ĐIỂM :
--    • Standalone: KHÔNG phụ thuộc seed_data_new.sql, KHÔNG truncate bảng nào khác.
--      Chỉ DELETE đúng 3 bảng của chính nó rồi INSERT lại với UUID CỐ ĐỊNH
--      ⇒ idempotent, chạy lại bao nhiêu lần cũng ra cùng kết quả.
--    • Bọc trong 1 transaction (BEGIN/COMMIT) — lỗi giữa chừng rollback hết.
--    • Mọi enum lưu DƯỚI DẠNG SỐ (integer), khớp Domain/Enum/Loi/.
--
--  CẤU TRÚC BẢNG CHUẨN (2 chiều) :
--    "FieldName"  = nhãn DÒNG trong Phụ lục 02 — dùng để HIỂN THỊ cho người dùng
--                   ("thiếu Mác bê tông").
--    "ParamName"  = tên tham số chuẩn ở tiêu đề CỘT — dùng để DÒ property trong file IFC
--                   ("Mô tả vật liệu"). Một nhãn dòng có thể trải trên nhiều tham số
--                   ⇒ nhiều dòng cùng "FieldName" (điều kiện HOẶC: có 1 tham số là đạt).
--    "Variant"    = biến thể trong cùng một mã cấu kiện ("Sàn bê tông" / "Sàn ngăn cháy").
--                   NULL = mã chỉ có một bộ trường. Cấu kiện đạt nếu khớp MỘT biến thể bất kỳ.
--    "Stage"      = giai đoạn bắt buộc: 2 TK cơ sở · 3 TK kỹ thuật · 4 TK BVTC · 5 Thi công.
--    "Discipline" = 0 Kiến trúc–Kết cấu (mã 21 01/02/03) · 1 MEP (mã 21 04).
--    "ParamGroup" = 1 Định danh · 2 Định vị · 3 Hình học · 4 Quy cách · 5 Vật liệu.
--
--  BA BẢNG LÀM GÌ :
--    "LoiRequirements" = YÊU CẦU — cấu kiện nào cần trường nào, từ giai đoạn nào.
--    "LoiComponents"   = CÂY PHÂN LOẠI đầy đủ, kể cả mã mà chuẩn KHÔNG quy định
--                        trường nào (vd "Móng băng"). Có bảng này hệ thống mới phân biệt
--                        được "model không khai mã" với "chuẩn để trống" — hai chuyện khác hẳn.
--    "LoiFieldAliases" = TỪ ĐIỂN TÊN — quy tên trong model về tên tham số chuẩn.
--
--  Quy ước UUID (segment đầu = "mã bảng", theo seed_data_new.sql):
--    50*=LoiRequirements   51*=LoiFieldAliases   52*=LoiComponents
-- ============================================================================

BEGIN;

-- --- Dọn bộ luật cũ ---------------------------------------------------------
--  LoiRequirements + LoiComponents: chỉ chứa dữ liệu của script này -> xoá sạch.
DELETE FROM "LoiRequirements";
DELETE FROM "LoiComponents";
--  LoiFieldAliases: GIỮ NGUYÊN alias riêng của từng dự án (ProjectId khác NULL) do
--  người quản lý dự án đã xác nhận — chỉ nạp lại phần dùng chung.
DELETE FROM "LoiFieldAliases" WHERE "ProjectId" IS NULL;

-- ============================================================================
--  1) LoiRequirements — 2871 dòng
--     Kiến trúc–Kết cấu : 49 cấu kiện · 78 biến thể · 1561 dòng
--     MEP               : 28 cấu kiện · 83 biến thể · 1310 dòng
-- ============================================================================
















-- ============================================================================
--  1b) LoiComponents — 328 dòng: CÂY PHÂN LOẠI ĐẦY ĐỦ của Phụ lục 02
--      Gồm CẢ những mã mà chuẩn KHÔNG quy định trường LOI nào (vd "Móng băng").
--      Nhờ đó hệ thống phân biệt được "model không khai mã" với "chuẩn để trống"
--      thay vì gộp chung thành "Chưa khai loại" gây hiểu lầm.
--      Kiến trúc–Kết cấu 223 · MEP 105
-- ============================================================================



-- ============================================================================
--  2) LoiFieldAliases — 169 dòng
--     Tên khác của TÊN THAM SỐ CHUẨN hay gặp trong file IFC do Revit xuất
--     (vd "Tên tầng" ← "Level"; "Khối tích" ← "Thể tích"; "Mô tả vật liệu" ← "Mác bê tông").
--     "ProjectId" = NULL ⇒ alias DÙNG CHUNG toàn hệ thống. Alias riêng của từng dự án do
--     người quản lý dự án xác nhận từ gợi ý ánh xạ (POST api/projects/{id}/loi-aliases) —
--     script này KHÔNG đụng tới chúng vì chúng có "ProjectId" khác NULL.
-- ============================================================================


COMMIT;

-- ============================================================================
--  KIỂM TRA NHANH SAU KHI CHẠY
-- ----------------------------------------------------------------------------
--    SELECT "Discipline", COUNT(DISTINCT "ComponentCode") AS cau_kien, COUNT(*) AS dong
--    FROM "LoiRequirements" GROUP BY "Discipline";
--      → Discipline 0 : 49 cấu kiện · 1561 dòng
--      → Discipline 1 : 28 cấu kiện · 1310 dòng
--    SELECT COUNT(*) FROM "LoiComponents";
--      → 328   (cây phân loại đầy đủ, kể cả mã chuẩn để trống)
--    SELECT COUNT(*) FROM "LoiFieldAliases";
--      → 169
--
--  THIẾU BẤT KỲ BẢNG NÀO Ở TRÊN LÀ TAB KIỂM LOI CHẠY SAI:
--    LoiRequirements rỗng -> mọi file đều "Không đánh giá được".
--    LoiComponents  rỗng -> mã hợp lệ nhưng chuẩn để trống bị báo nhầm "Chưa khai loại".
-- ============================================================================
